SEED_TEST_DELAY_SECONDS = 5


def run_seed_test(conn: sqlite3.Connection):
    seed_items = get_seed_news_items()
    total = len(seed_items)
    log.info("=" * 60)
    log.info(f"প্রথম রান শনাক্ত হয়েছে — {total}টি টেস্ট নিউজ পাঠানো শুরু হচ্ছে...")
    log.info("=" * 60)

    success_count = 0
    for idx, item in enumerate(seed_items, start=1):
        log.info(f"[টেস্ট {idx}/{total}] প্রসেস করা হচ্ছে: {item.title}")
        processed_ok = False
        for retry in range(2):
            try:
                process_item(conn, item)
                processed_ok = True
                break
            except Exception as e:
                if retry == 0:
                    log.warning(f"[টেস্ট {idx}/{total}] সাময়িক এরর হয়েছে, একবার রিট্রাই করা হচ্ছে: {e}")
                    time.sleep(3)
                else:
                    log.error(f"[টেস্ট {idx}/{total}] রিট্রাই করেও ব্যর্থ হয়েছে, পরের আইটেমে যাওয়া হচ্ছে: {e}")
        if processed_ok:
            success_count += 1

        if idx < total:
            log.info(f"[টেস্ট {idx}/{total}] সম্পন্ন — পরের টেস্ট আইটেমের আগে {SEED_TEST_DELAY_SECONDS} সেকেন্ড অপেক্ষা করা হচ্ছে।")
            time.sleep(SEED_TEST_DELAY_SECONDS)

    log.info(f"টেস্ট নিউজ পাঠানো সম্পন্ন হয়েছে ({success_count}/{total} সফলভাবে প্রসেস হয়েছে)।")


# ---------------------------------------------------------------------------
# ফেচার — RSS নিউজ ও Telegram চ্যানেল পোস্ট
# ---------------------------------------------------------------------------
def clean_html(raw_html: str) -> str:
    if not raw_html:
        return ""
    soup = BeautifulSoup(raw_html, "html.parser")
    return soup.get_text(separator=" ", strip=True)


def _normalize_image_url(url: str) -> str:
    try:
        parts = urllib.parse.urlsplit(url.strip())
        normalized_path = parts.path.rstrip("/")
        return urllib.parse.urlunsplit(
            (parts.scheme.lower(), parts.netloc.lower(), normalized_path, "", "")
        )
    except Exception:
        return (url or "").strip()


def dedupe_image_urls(urls: List[str]) -> List[str]:
    seen = set()
    unique: List[str] = []
    for url in urls:
        if not url:
            continue
        key = _normalize_image_url(url)
        if key in seen:
            continue
        seen.add(key)
        unique.append(url)
    return unique


def entry_has_video(entry) -> bool:
    """একটি RSS এন্ট্রিতে ভিডিও, GIF, বা ভিডিও-থাম্বনেইল আছে কিনা
    শনাক্ত করে। ভিডিও থাকলে সেটা কখনোই সরাসরি ডাউনলোড/পাঠানো হয় না — বরং
    ছবি-বিহীন ধরে Pollinations.ai দিয়ে AI ছবি জেনারেট করে পাঠানো হয়।"""
    for m in getattr(entry, "media_content", []) or []:
        medium = str(m.get("medium", "")).lower()
        mtype = str(m.get("type", "")).lower()
        if medium == "video" or mtype.startswith("video") or "gif" in mtype:
            return True

    for link in getattr(entry, "links", []) or []:
        ltype = str(link.get("type", "")).lower()
        if ltype.startswith("video") or "gif" in ltype:
            return True

    html_blob = ""
    if hasattr(entry, "summary"):
        html_blob += entry.summary or ""
    for c in getattr(entry, "content", []) or []:
        html_blob += c.get("value", "") or ""
    if html_blob:
        lowered = html_blob.lower()
        if "<video" in lowered or ".mp4" in lowered or "video_thumb" in lowered:
            return True

    return False


def extract_images_from_entry(entry) -> List[str]:
    """RSS এন্ট্রি থেকে ছবির URL বের করার চেষ্টা করে (media:content,
    media:thumbnail, enclosure, অথবা HTML এর ভেতরের <img>)। যেহেতু বট
    কখনোই অ্যালবাম/একাধিক ছবি পাঠায় না (দেখুন post_news_item), শুধুমাত্র
    প্রথম ইউনিক ছবিটি রিটার্ন করা হয় — normalized-dedupe এর পরে। এন্ট্রিতে
    ভিডিও/GIF থাকলে (entry_has_video) কোনো ছবিই রিটার্ন করা হয় না, তখন
    fetch_rss_news পরে Pollinations.ai দিয়ে AI ছবি
    জেনারেট করবে।"""
    if entry_has_video(entry):
        return []

    images: List[str] = []

    for m in getattr(entry, "media_content", []) or []:
        url = m.get("url")
        if url:
            images.append(url)

    for m in getattr(entry, "media_thumbnail", []) or []:
        url = m.get("url")
        if url:
            images.append(url)

    for link in getattr(entry, "links", []) or []:
        if link.get("rel") == "enclosure" and str(link.get("type", "")).startswith("image"):
            url = link.get("href")
            if url:
                images.append(url)

    html_blob = ""
    if hasattr(entry, "summary"):
        html_blob += entry.summary or ""
    for c in getattr(entry, "content", []) or []:
        html_blob += c.get("value", "") or ""
    if html_blob:
        soup = BeautifulSoup(html_blob, "html.parser")
        for img in soup.find_all("img"):
            src = img.get("src")
            if src:
                images.append(src)

    # শুধুমাত্র প্রথম ইউনিক (primary) ছবিটি রাখা হয় — কখনো অ্যালবাম পাঠানো
    # হয় না, তাই একাধিক ছবি সংগ্রহ করার দরকার নেই।
    return dedupe_image_urls(images)[:1]


def parse_feed_safely(feed_url: str, timeout: int = None):
    """RSS ফিড টাইমআউটসহ ফেচ করে feedparser দিয়ে পার্স করে। সরাসরি
    feedparser.parse(url) ব্যবহার করলে কোনো সার্ভার সাড়া না দিলে রিকোয়েস্টটি
    অনির্দিষ্টকাল আটকে থাকতে পারে — requests.get(timeout=...) ব্যবহার করে
    সেটা এড়ানো হয়েছে।"""
    resp = requests.get(
        feed_url,
        timeout=timeout or Config.FEED_FETCH_TIMEOUT_SECONDS,
        headers={"User-Agent": "Mozilla/5.0 (compatible; CryptoBartaBot/1.0)"},
    )
    resp.raise_for_status()
    return feedparser.parse(resp.content)


def _parse_rss_published_dt(entry) -> Optional[datetime]:
    """feedparser এন্ট্রি থেকে published/updated সময়কে timezone-aware UTC
    datetime এ রূপান্তর করে। কোনো টাইমস্ট্যাম্প পার্স করা না গেলে None
    রিটার্ন করে — is_item_fresh() তখন নিরাপদ থাকতে আইটেমটিকে fresh ধরে
    না, যাতে টাইমস্ট্যাম্পহীন কোনো পুরনো আইটেম ভুলবশত পোস্ট না হয়ে যায়।"""
    struct = entry.get("published_parsed") or entry.get("updated_parsed")
    if not struct:
        return None
    try:
        return datetime(*struct[:6], tzinfo=timezone.utc)
    except Exception:
        return None


def _parse_telegram_message_dt(message_div) -> Optional[datetime]:
    """একটি Telegram প্রিভিউ মেসেজের <a class="tgme_widget_message_date">
    এর ভেতরের <time datetime="..."> অ্যাট্রিবিউট থেকে timezone-aware UTC
    datetime বের করে। পার্স ব্যর্থ হলে None রিটার্ন করে।"""
    time_tag = message_div.select_one("a.tgme_widget_message_date time")
    if time_tag is None:
        return None
    raw = (time_tag.get("datetime") or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def is_item_fresh(published: Optional[datetime]) -> bool:
    """একটি আইটেম সত্যিকারের "just now"/ব্রেকিং কিনা যাচাই করে।

    কোনো পাবলিশড টাইমস্ট্যাম্পই পার্স করা না গেলে (None) নিরাপদ থাকতে সেটাকে
    fresh ধরা হয় না — বরং বাদ দেওয়া হয়, যাতে টাইমস্ট্যাম্পহীন কোনো পুরনো
    খবর ভুলবশত পোস্ট না হয়ে যায়।

    ফ্রেশ কাটঅফ হলো: max(বট চালু হওয়ার সময়, এখন - FRESH_WINDOW_SECONDS)।
    এভাবে বট সবেমাত্র চালু হলে (৫ মিনিটেরও কম আগে) শুধুই বট-চালু-হওয়ার-
    পরে পাবলিশ হওয়া আইটেম আসবে (কোনো ব্যাকফিল স্প্যাম নেই), আর বট অনেকক্ষণ
    ধরে চলতে থাকলে স্বাভাবিকভাবেই ৫ মিনিটের বেশি পুরনো আইটেম বাদ যাবে।"""
    if published is None:
        return False
    now = datetime.now(timezone.utc)
    cutoff = max(BOT_START_TIME, now - timedelta(seconds=Config.FRESH_WINDOW_SECONDS))
    return published >= cutoff


def fetch_rss_news() -> List[NewsItem]:
    """প্রাইমারি ও সবচেয়ে নির্ভরযোগ্য সোর্স — Cointelegraph, CoinDesk ও
    Decrypt এর অফিসিয়াল RSS ফিড থেকে সর্বশেষ খবরগুলো সংগ্রহ করে। কোনো একটা
    ফিড সাময়িকভাবে অকেজো থাকলে সেটা লগ করে বাকি ফিডগুলো থেকে সংগ্রহ চালিয়ে
    যায় — একটার ব্যর্থতায় পুরো সাইকেল থামে না।

    প্রতিটি এন্ট্রির published/updated টাইমস্ট্যাম্প যাচাই করা হয়
    (is_item_fresh) — বট চালু হওয়ার আগে পাবলিশ হওয়া বা ৫ মিনিটের বেশি
    পুরনো যেকোনো এন্ট্রি সঙ্গে সঙ্গে বাদ দেওয়া হয়, যাতে পুরনো
    খবরের "backfill" স্প্যাম না হয়।"""
    items: List[NewsItem] = []
    for feed_url in Config.RSS_FEEDS:
        try:
            parsed = parse_feed_safely(feed_url)
            source_name = parsed.feed.get("title", feed_url) if parsed.feed else feed_url
            fresh_count = 0
            stale_count = 0
            for entry in parsed.entries[:10]:
                link = entry.get("link")
                title = entry.get("title", "")
                if not link or not title:
                    continue
                published_dt = _parse_rss_published_dt(entry)
                if not is_item_fresh(published_dt):
                    stale_count += 1
                    continue
                summary = clean_html(entry.get("summary", "") or entry.get("description", ""))
                items.append(
                    NewsItem(
                        source_name=source_name,
                        source_type="rss",
                        title=title,
                        summary=summary[:600],
                        link=link,
                        images=extract_images_from_entry(entry),
                        published=published_dt,
                    )
                )
                fresh_count += 1
            if stale_count:
                log.info(
                    f"{source_name}: {fresh_count}টি ফ্রেশ + {stale_count}টি পুরনো "
                    "(৫ মিনিটের বেশি আগের/বট-চালুর আগের) আইটেম বাদ দেওয়া হলো"
                )
        except Exception as e:
            log.warning(f"RSS ফিড ফেচ করতে ব্যর্থ {feed_url}: {e}")
    return items


def _extract_telegram_message_image(message_div) -> List[str]:
    """একটি একক Telegram প্রিভিউ মেসেজ থেকে ছবির URL বের করার চেষ্টা করে —
    .tgme_widget_message_photo_wrap (বা .tgme_widget_message_video_thumb) এর
    inline style এর ভেতরে background-image: url('...') হিসেবে থাকে।
    ভিডিও পোস্ট হলে (tgme_widget_message_video_wrap পাওয়া গেলে) কখনোই সেই
    থাম্বনেইল/ভিডিও ব্যবহার করা হয় না — খালি লিস্ট রিটার্ন করা হয়, যাতে
    caller (fetch_telegram_news) সেটাকে ছবি-বিহীন ধরে পরে Pollinations.ai
    দিয়ে AI ছবি বানিয়ে নেয়।"""
    if message_div.select_one(
        ".tgme_widget_message_video_wrap, .tgme_widget_message_video, "
        ".tgme_widget_message_roundvideo"
    ):
        return []

    images: List[str] = []
    photo_wrap = message_div.select_one(".tgme_widget_message_photo_wrap")
    if photo_wrap is not None:
        style = photo_wrap.get("style", "") or ""
        m = re.search(r"url\((['\"]?)(.*?)\1\)", style)
        if m and m.group(2):
            images.append(m.group(2))

    return dedupe_image_urls(images)[:1]


def fetch_telegram_news() -> List[NewsItem]:
    """সেকেন্ডারি নিউজ সোর্স — পাবলিক Telegram চ্যানেলগুলো
    (Config.TELEGRAM_CHANNELS, যেমন WatcherGuru ও Cointelegraph) থেকে
    সাম্প্রতিক পোস্ট সংগ্রহ করে। এটি Telegram এর অফিসিয়াল Bot/Client API
    ব্যবহার করে না (কোনো লগইন/সেশন/টোকেন লাগে না) — বরং প্রতিটি পাবলিক
    চ্যানেলের জন্য উন্মুক্ত ওয়েব-প্রিভিউ পেইজ (https://t.me/s/<channel>)
    সরাসরি `requests` দিয়ে ফেচ করে `BeautifulSoup` দিয়ে পার্স করা হয়।

    প্রতিটি মেসেজ ব্লক (.tgme_widget_message_wrap) থেকে টেক্সট
    (.tgme_widget_message_text), প্রাইমারি ছবি
    (.tgme_widget_message_photo_wrap) এবং পার্মালিংক
    (a.tgme_widget_message_date) বের করা হয়। যে পোস্টে কোনো টেক্সট নেই
    (শুধুই ছবি/ভিডিও/ফরওয়ার্ড হেডার) সেটা স্কিপ করা হয়, কারণ headline
    জেনারেট করার মতো কোনো কনটেন্ট নেই।

    কোনো চ্যানেল ফেচ/পার্স করতে ব্যর্থ হলে (নেটওয়ার্ক এরর, টাইমআউট,
    Telegram এর HTML structure বদলে যাওয়া, ইত্যাদি) exception ধরে সেটা লগ
    করে গ্রেসফুলি স্কিপ করে পরের চ্যানেলে চলে যাওয়া হয় — পুরো পোলিং লুপ
    কখনো ক্র্যাশ করে না।

    ডিডুপ্লিকেশন RSS এর মতোই SQLite link hash (NewsItem.link_hash) দিয়ে হয়
    (process_item/is_link_seen), তাই এখানে আলাদা কিছু করার দরকার নেই।
    """
    if not Config.ENABLE_TELEGRAM_SOURCE:
        return []

    items: List[NewsItem] = []
    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
        )
    }

    for channel in Config.TELEGRAM_CHANNELS:
        url = f"{Config.TELEGRAM_PREVIEW_BASE}{channel}"
        try:
            resp = requests.get(
                url,
                headers=headers,
                timeout=Config.FEED_FETCH_TIMEOUT_SECONDS,
            )
            resp.raise_for_status()
        except Exception as e:
            log.warning(f"Telegram চ্যানেল ফেচ ব্যর্থ @{channel} ({url}): {e}")
            continue

        try:
            soup = BeautifulSoup(resp.text, "html.parser")
            message_wraps = soup.select("div.tgme_widget_message_wrap")
            if not message_wraps:
                log.warning(
                    f"@{channel} এর প্রিভিউ পেইজে কোনো মেসেজ পাওয়া যায়নি — "
                    "চ্যানেলটি প্রাইভেট/অস্তিত্বহীন হতে পারে অথবা Telegram "
                    "HTML structure বদলে গেছে, এই সাইকেলে স্কিপ করা হচ্ছে"
                )
                continue

            # পেইজের নিচের দিকের ব্লকগুলোই সবচেয়ে সাম্প্রতিক পোস্ট।
            recent_wraps = message_wraps[-Config.TELEGRAM_MAX_POSTS_PER_CHANNEL :]
            fresh_count = 0
            stale_count = 0
            for wrap in recent_wraps:
                try:
                    text_div = wrap.select_one(".tgme_widget_message_text")
                    if text_div is None:
                        continue  # শুধু মিডিয়া/ফরওয়ার্ড, কোনো টেক্সট নেই
                    text = clean_html(str(text_div))
                    if not text:
                        continue

                    date_link = wrap.select_one("a.tgme_widget_message_date")
                    link = date_link.get("href") if date_link is not None else None
                    if not link:
                        continue

                    published_dt = _parse_telegram_message_dt(wrap)
                    if not is_item_fresh(published_dt):
                        stale_count += 1
                        continue

                    images = _extract_telegram_message_image(wrap)

                    items.append(
                        NewsItem(
                            source_name=f"@{channel}",
                            source_type="telegram",
                            title=text[:200],
                            summary=text[:600],
                            link=link,
                            images=images,
                            published=published_dt,
                        )
                    )
                    fresh_count += 1
                except Exception as e:
                    log.warning(f"@{channel} এর একটি মেসেজ পার্স করতে ব্যর্থ: {e}")
                    continue

            log.info(
                f"@{channel}: {len(recent_wraps)}টি পোস্ট চেক করে {fresh_count}টি ফ্রেশ "
                f"পাওয়া গেছে ({stale_count}টি পুরনো/বট-চালুর আগের বাদ দেওয়া হলো)"
            )
        except Exception as e:
            log.warning(f"@{channel} এর HTML পার্স করতে ব্যর্থ: {e}")
            continue

    return items


# ---------------------------------------------------------------------------
# Gemini (ফ্রি) দিয়ে ইম্পরট্যান্স ফিল্টার + সেন্টিমেন্ট + বাংলা হেডলাইন +
# ইমোজি তৈরি
# ---------------------------------------------------------------------------
_genai_client = None

DEFAULT_EMOJI = "🚨"  # ইমোজি নির্বাচন ব্যর্থ হলে এই ডিফল্ট ইমোজি ব্যবহার হবে
DEFAULT_SENTIMENT = "NEUTRAL"  # সেন্টিমেন্ট পার্স করা না গেলে এই ডিফল্ট ব্যবহার হবে


def get_genai_client():
    global _genai_client
    if _genai_client is None:
        _genai_client = genai.Client(api_key=Config.GEMINI_API_KEY)
    return _genai_client


def ai_rate_limit_sleep():
    delay = random.uniform(Config.AI_CALL_MIN_DELAY, Config.AI_CALL_MAX_DELAY)
    time.sleep(delay)


def _is_rate_limit_error(exc: Exception) -> bool:
    text = str(exc).lower()
    return "429" in text or "resource_exhausted" in text or "quota" in text


def _call_gemini(prompt: str):
    client = get_genai_client()
    models_to_try = [Config.GEMINI_TEXT_MODEL, Config.GEMINI_FALLBACK_MODEL]
    last_exc = None
    for model_name in models_to_try:
        try:
            resp = client.models.generate_content(model=model_name, contents=prompt)
            return resp
        except Exception as e:
            last_exc = e
            if _is_rate_limit_error(e):
                log.warning(f"মডেল '{model_name}' কোটা/রেট-লিমিটে ব্যর্থ, ফলব্যাক মডেল চেষ্টা করা হচ্ছে: {e}")
                continue
            raise
        finally:
            ai_rate_limit_sleep()
    raise last_exc


# হেডলাইন + ইমোজি + ইম্পরট্যান্স-ফিল্টার + সেন্টিমেন্ট তৈরির জন্য প্রম্পট
# টেমপ্লেট। মডেলকে JSON ফরম্যাটে উত্তর দিতে বলা হয়েছে যাতে প্রতিটি ফিল্ড
# আলাদাভাবে নির্ভরযোগ্যভাবে বের করা যায়।
HEADLINE_PROMPT_TEMPLATE = """You are a professional Bengali crypto news editor and market analyst for a Telegram breaking-news channel.

STEP 1 — HIGH-IMPACT FILTER (decide this first):
Set "is_important" to true ONLY if this news is genuinely significant for the
overall crypto market, such as:
  - A breaking / emergency market-moving event
  - A major regulatory move (SEC/government decision, ban, approval, court ruling)
  - A large hack, exploit, or exchange security breach
  - A major spot/futures ETF update (filing, approval, huge inflow/outflow)
  - A central bank or government monetary-policy decision affecting crypto
  - A major institutional partnership, investment, or adoption announcement
  - An extreme volatility driver (new all-time high, flash crash, huge liquidation)
Set "is_important" to false for anything else: routine price commentary,
generic opinion/analysis, sponsored/promotional content, minor altcoin noise,
or any story that is not clearly significant for the broader market. When in
doubt between routine and significant, prefer false — this channel only wants
truly high-impact news.
If "is_important" is false, "headline" can be a short placeholder — it will
not be used or posted.

STEP 2 — MARKET SENTIMENT:
"sentiment" MUST be EXACTLY one of these three strings: "BULLISH", "BEARISH",
or "NEUTRAL" — never any other word.
  - Use "BULLISH" when the news has a clearly positive/upward market impact
    (e.g. ETF inflow, major adoption, bullish price breakout, favorable
    regulation).
  - Use "BEARISH" when the news has a clearly negative/downward market impact
    (e.g. hack, ban, lawsuit, crash, outflow, regulatory crackdown).
  - Use "NEUTRAL" when the impact is moderate/low, purely informational, or
    balanced/mixed with no clear directional lean (e.g. a routine but
    still-notable announcement, a delayed decision with no verdict yet, a
    general market-structure update).

STEP 3 — EMOJI (only matters if is_important is true):
"emoji": ONE or TWO emoji characters (as a single string, no spaces) chosen
   intelligently based on the context of the news:
   - Breaking / emergency / hack / exploit / crash news -> use 🚨 or ⚠️ or 💥
   - Bullish / price surge / all-time-high news -> use 🚀 or 📈 or 🟢
   - Bearish / regulatory ban / negative news -> use 📉 or 🔴
   - General listing / partnership / announcement news -> use 📢 or 🤝 or 💎
   - If the news is specific to a particular country (e.g. USA, UAE, El Salvador,
     India, UK, Japan, South Korea, China, etc.), APPEND that country's flag
     emoji right after the category emoji (example: "🚨🇺🇸", "🚀🇸🇻", "📉🇮🇳").
   - If no specific country is mentioned, use only the category emoji (no flag).

STEP 4 — HEADLINE (only matters if is_important is true):
"headline": a single Bengali (বাংলা) sentence that is a CORE INCIDENT
   SUMMARY of the news — not a generic teaser.

STRICT RULES FOR "headline":
- It MUST state the specific WHAT HAPPENED: the concrete event, action,
  number, amount, percentage, entity name, or outcome taken directly from
  the "Title"/"Details" below. Name who did what, to whom/what, and any
  figures involved, exactly like a news-agency one-line summary.
  Example of the CORRECT style: "নর্থ কোরিয়ার হ্যাকারদের হামলায় বিটগেটের
  ৩৫২ মিলিয়ন ডলার ক্ষতি হয়েছে বলে সন্দেহ করা হচ্ছে।"
- It is STRICTLY FORBIDDEN to write generic teaser/filler phrases such as
  "আজকের সেরা খবর", "বিস্তারিত জেনে নিন", "দামের ওঠানামা", "জেনে নিন",
  "সর্বশেষ খবর", or any sentence that only says news exists without stating
  the actual fact. If you catch yourself writing a teaser, rewrite it as a
  factual summary instead.
- Bengali text ONLY. No quotes, no English words, no hashtags, and NO emoji
  inside this field (the emoji goes only in the separate "emoji" field above).
- Length MUST be between {min_c} and {max_c} characters (including spaces).
- Base it strictly on the facts given below — never invent numbers or facts
  that are not present in the content. If the content has no specific number,
  summarize the specific action/decision/entity instead.

Respond with ONLY a valid JSON object in this exact shape, nothing else,
no markdown code fences, no explanation:
{{"is_important": true/false, "sentiment": "BULLISH"/"BEARISH"/"NEUTRAL", "emoji": "...", "headline": "..."}}

CONTENT:
Title: {title}
Details: {summary}
"""


def _parse_headline_json(raw_text: str) -> Optional[dict]:
    cleaned = raw_text.strip()
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", cleaned, flags=re.IGNORECASE)
    try:
        return json.loads(cleaned)
    except (json.JSONDecodeError, TypeError):
        return None


def _sanitize_emoji(emoji: str) -> str:
    emoji = (emoji or "").strip()
    if not emoji or len(emoji) > 8:
        return DEFAULT_EMOJI
    if re.search(r"[A-Za-z\u0980-\u09FF]", emoji):  # ইংরেজি বা বাংলা অক্ষর থাকলে
        return DEFAULT_EMOJI
    return emoji


def _sanitize_sentiment(sentiment) -> str:
    """সেন্টিমেন্ট ফিল্ডকে কড়াভাবে শুধু "BULLISH", "BEARISH" বা "NEUTRAL"
    এর মধ্যে সীমাবদ্ধ রাখে — Gemini অন্য কিছু (mixed, unclear, ইত্যাদি)
    লিখে ফেললেও ক্যাপশনে কখনো সেটা যাবে না, বরং NEUTRAL এ পড়ে যাবে।"""
    value = str(sentiment or "").strip().upper()
    if value in ("BULLISH", "BEARISH", "NEUTRAL"):
        return value
    return DEFAULT_SENTIMENT


TEASER_PHRASES_BN = [
    "সেরা খবর",
    "বিস্তারিত জেনে নিন",
    "জেনে নিন",
    "সর্বশেষ খবর",
    "দামের ওঠানামা",
    "আজকের খবর",
]


def _headline_has_teaser_phrase(headline: str) -> bool:
    return any(phrase in headline for phrase in TEASER_PHRASES_BN)


def generate_bengali_headline(item: NewsItem) -> Optional[Tuple[str, str, str]]:
    """Gemini দিয়ে প্রথমে খবরটি high-impact কিনা যাচাই করে (is_important) —
    না হলে সঙ্গে সঙ্গে None রিটার্ন করে দেয়, যাতে caller (process_item) সেটা
    সম্পূর্ণভাবে স্কিপ করে দেয়। high-impact হলে মার্কেট সেন্টিমেন্ট
    (BULLISH/BEARISH), ১০০-১৫০ অক্ষরের বাংলা "কোর ইনসিডেন্ট সামারি" হেডলাইন,
    এবং প্রাসঙ্গিক ইমোজি তৈরি করে (emoji, headline, sentiment) টাপল রিটার্ন
    করে। ফরম্যাট/দৈর্ঘ্য ঠিক না হলে সর্বোচ্চ ৩ বার চেষ্টা করে।"""
    prompt = HEADLINE_PROMPT_TEMPLATE.format(
        min_c=Config.HEADLINE_MIN_CHARS,
        max_c=Config.HEADLINE_MAX_CHARS,
        title=item.title,
        summary=item.summary[:500],
    )
    for attempt in range(3):
        try:
            resp = _call_gemini(prompt)
            data = _parse_headline_json(resp.text or "")
            if not data:
                log.warning(f"JSON পার্স করা যায়নি, আবার চেষ্টা করা হচ্ছে ({attempt + 1}/3)")
                continue

            is_important = bool(data.get("is_important", False))
            if not is_important:
                log.info(f"কম-গুরুত্বপূর্ণ/রুটিন খবর হিসেবে স্কিপ করা হলো (is_important=false): {item.link}")
                return None

            sentiment = _sanitize_sentiment(data.get("sentiment"))
            headline = str(data.get("headline", "")).strip().strip('"').strip()
            headline = re.sub(r"\s+", " ", headline)
            emoji = _sanitize_emoji(str(data.get("emoji", "")))
            length = len(headline)

            if _headline_has_teaser_phrase(headline):
                log.info(f"টিজার/জেনেরিক বাক্য ধরা পড়েছে, আবার চেষ্টা করা হচ্ছে ({attempt + 1}/3): {headline}")
                prompt += (
                    "\n\nYour previous attempt used a generic teaser phrase instead of "
                    "stating the core incident/fact. Rewrite it as a specific factual "
                    "summary of what actually happened, with names/numbers from the "
                    "content. Keep is_important and sentiment the same. Respond with "
                    "the same JSON shape."
                )
                continue

            if Config.HEADLINE_MIN_CHARS <= length <= Config.HEADLINE_MAX_CHARS:
                return emoji, headline, sentiment

            log.info(f"হেডলাইনের দৈর্ঘ্য {length} — সীমার বাইরে, আবার চেষ্টা করা হচ্ছে ({attempt + 1}/3)")
            prompt += (
                f"\n\nYour previous attempt was {length} characters. "
                f"Rewrite it strictly between {Config.HEADLINE_MIN_CHARS} and "
                f"{Config.HEADLINE_MAX_CHARS} characters. Keep is_important and "
                "sentiment the same. Respond with the same JSON shape."
            )
        except Exception as e:
            log.warning(f"Gemini হেডলাইন তৈরিতে ব্যর্থ (চেষ্টা {attempt + 1}): {e}")
    return None


NEGATIVE_IMAGE_GUIDANCE = (
    "no text, no letters, no words, no captions, no watermark, no Bengali script, "
    "clean background, professional 3d render, cinematic lighting, 4k, high quality"
)


def generate_image_prompt(item: NewsItem) -> str:
    prompt = (
        "Create a short English visual-concept prompt (max 30 words) for an AI "
        "image generator, for a crypto news illustration. Cinematic, "
        "3D-rendered / futuristic finance style, 4k.\n"
        "IMPORTANT CONSTRAINTS:\n"
        "- Do NOT describe or request any text, letters, words, captions, or "
        "Bengali script anywhere in the image.\n"
        "- If a coin symbol/logo (e.g. BTC, ETH, BNB) is relevant, describe it "
        "ONLY as a clean, professional, standard English typographic logo — "
        "never distorted, never random overlaid text.\n"
        "- Keep the background clean and uncluttered.\n\n"
        f"Base the visual concept on this news:\nTitle: {item.title}\n"
        f"Details: {item.summary[:300]}\n"
        "Output ONLY the prompt text, nothing else."
    )
    try:
        resp = _call_gemini(prompt)
        text = (resp.text or "").strip()
        if text:
            return text
    except Exception as e:
        log.warning(f"ছবির প্রম্পট তৈরিতে ব্যর্থ: {e}")
    return f"futuristic 3d render of {item.title}, glowing crypto chart, dark background"


def _strip_pollinations_watermark(image_bytes: bytes) -> bytes:
    """Pollinations.ai কে nologo=true পাঠানো সত্ত্বেও মাঝে মাঝে ছবির একদম
    নিচের কোণায় ছোট "pollinations.ai" ওয়াটারমার্ক টেক্সট রয়ে যায়। এটা
    নিশ্চিতভাবে সরাতে ছবির নিচের কয়েক পিক্সেল (Config.
    POLLINATIONS_WATERMARK_CROP_PX) সরাসরি ক্রপ করে ফেলা হয়, তারপর
    Telegram এ পোস্ট করার সময় অনুপাত/সাইজ যেন স্বাভাবিক থাকে সেজন্য আবার
    মূল উচ্চতায় resize করে PNG bytes হিসেবে ফেরত দেওয়া হয়। ছবির
    bytes করাপ্ট/অপঠনযোগ্য হলে (Pillow দিয়ে ওপেন করতে ব্যর্থ হলে) এই
    ফাংশন কখনো exception রেইজ করে না — বরং মূল bytes-ই অপরিবর্তিত ফেরত
    দিয়ে দেয়, যাতে পুরো ছবি-জেনারেশন পাইপলাইন কখনো ক্র্যাশ না করে।"""
    try:
        img = Image.open(io.BytesIO(image_bytes)).convert("RGB")
        width, height = img.size
        crop_px = min(Config.POLLINATIONS_WATERMARK_CROP_PX, max(height // 4, 0))
        if crop_px <= 0:
            buf = io.BytesIO()
            img.save(buf, format="PNG")
            return buf.getvalue()
        cropped = img.crop((0, 0, width, height - crop_px))
        cropped = cropped.resize((width, height), Image.LANCZOS)
        buf = io.BytesIO()
        cropped.save(buf, format="PNG")
        return buf.getvalue()
    except Exception as e:
        log.warning(f"Pollinations ওয়াটারমার্ক ক্রপ করতে ব্যর্থ, মূল ছবি ব্যবহার করা হচ্ছে: {e}")
        return image_bytes


def generate_ai_image_bytes(prompt: str) -> Optional[bytes]:
    """সম্পূর্ণ ফ্রি Pollinations.ai ব্যবহার করে ছবি তৈরি করে — কোনো API key,
    সাইনআপ বা ক্রেডিট কার্ড লাগে না। ওয়াটারমার্ক/লোগো সরাতে nologo=true &
    nofeed=true, সেরা কোয়ালিটির জন্য model=flux (Config.
    POLLINATIONS_EXTRA_PARAMS) যোগ করা হয়েছে, এবং তারপরও কোনো
    ওয়াটারমার্ক অবশিষ্ট থাকলে সেটা _strip_pollinations_watermark দিয়ে
    ছবির নিচের অংশ ক্রপ করে নিশ্চিতভাবে সরিয়ে ফেলা হয়।"""
    if not Config.ENABLE_AI_IMAGE:
        return None
    try:
        final_prompt = f"{prompt}, {NEGATIVE_IMAGE_GUIDANCE}"
        encoded_prompt = urllib.parse.quote(final_prompt)
        image_url = (
            f"{Config.POLLINATIONS_BASE}/{encoded_prompt}"
            f"?width={Config.POLLINATIONS_WIDTH}&height={Config.POLLINATIONS_HEIGHT}"
            f"&{Config.POLLINATIONS_EXTRA_PARAMS}"
        )
        resp = requests.get(image_url, timeout=90)
        resp.raise_for_status()
        if resp.headers.get("content-type", "").startswith("image"):
            return _strip_pollinations_watermark(resp.content)
        log.warning("Pollinations.ai থেকে ছবি আসেনি (ভুল content-type)")
    except Exception as e:
        log.warning(f"Pollinations.ai ছবি তৈরিতে ব্যর্থ: {e}")
    return None


# ---------------------------------------------------------------------------
# টেলিগ্রাম পোস্টিং
# ---------------------------------------------------------------------------
TELEGRAM_API = "https://api.telegram.org/bot{token}/{method}"


def tg_url(method: str) -> str:
    return TELEGRAM_API.format(token=Config.TELEGRAM_BOT_TOKEN, method=method)


def build_caption(
    emoji: str, headline_bn: str, source_link: str, sentiment: str, source_type: str
) -> str:
    """ক্যাপশন তৈরি করে — হেডলাইনের পরে, Source/Follow লিংকের আগে একটি
    সম্পূর্ণ ইংরেজি "MARKET HINT" লাইন যোগ করা হয়েছে, যা Gemini এর
    সেন্টিমেন্ট বিশ্লেষণ অনুযায়ী BULLISH 🟢 / BEARISH 🔴 / NEUTRAL ⚪
    এর একটি দেখায়। "🌐 Source" লাইনটি শুধুমাত্র RSS সোর্সের আইটেমের জন্য
    যোগ করা হয় — Telegram চ্যানেল থেকে আসা আইটেমে (source_type ==
    "telegram") এই লাইন সম্পূর্ণভাবে বাদ দেওয়া হয়।"""
    sentiment = _sanitize_sentiment(sentiment)
    if sentiment == "BULLISH":
        sentiment_emoji = "🟢"
    elif sentiment == "BEARISH":
        sentiment_emoji = "🔴"
    else:
        sentiment_emoji = "⚪"

    caption = (
        f"{emoji} <b>{headline_bn}</b>\n\n"
        f"📊 <b>MARKET HINT:</b> <b>{sentiment}</b> {sentiment_emoji}\n\n"
    )
    if source_type != "telegram":
        caption += f'🌐 <b>Source:</b> <a href="{source_link}">Click Here</a>\n\n'
    caption += f'🔔 <b>Follow:</b> <a href="{Config.FOLLOW_CHANNEL_URL}"><b>CRYPTO BARTA</b></a>'
    return caption


def send_text_message(caption: str) -> bool:
    """ছবি ছাড়া শুধু টেক্সট পোস্ট করে (যখন কোনো ছবিই পাওয়া যায়নি)।
    disable_web_page_preview=true পাঠানো হয় যাতে ক্যাপশনের ভেতরের Source/
    Follow লিংক থেকে Telegram স্বয়ংক্রিয়ভাবে কোনো webpage preview কার্ড
    (নিচে অতিরিক্ত বক্স) দেখিয়ে না দেয় — মেসেজটা পরিষ্কার/ক্লিন থাকে।"""
    try:
        resp = requests.post(
            tg_url("sendMessage"),
            data={
                "chat_id": Config.TELEGRAM_CHANNEL_ID,
                "text": caption,
                "parse_mode": "HTML",
                "disable_web_page_preview": "true",
            },
            timeout=30,
        )
        resp.raise_for_status()
        return True
    except Exception as e:
        log.error(f"sendMessage ব্যর্থ: {e}")
        return False


def send_single_photo(caption: str, image_url: str = None, image_bytes: bytes = None) -> bool:
    """একটি ছবিসহ পোস্ট করে — সোর্স URL অথবা ডাউনলোড করা bytes, দুটোই সাপোর্ট
    করে। বট কখনোই sendMediaGroup (অ্যালবাম) ব্যবহার করে না — সবসময় ঠিক
    একটি ছবি sendPhoto দিয়ে পাঠানো হয়।"""
    try:
        data = {
            "chat_id": Config.TELEGRAM_CHANNEL_ID,
            "caption": caption,
            "parse_mode": "HTML",
        }
        if image_bytes:
            files = {"photo": ("image.jpg", io.BytesIO(image_bytes))}
            resp = requests.post(tg_url("sendPhoto"), data=data, files=files, timeout=60)
        else:
            data["photo"] = image_url
            resp = requests.post(tg_url("sendPhoto"), data=data, timeout=60)
        resp.raise_for_status()
        return True
    except Exception as e:
        log.error(f"sendPhoto ব্যর্থ: {e}")
        return False


def post_news_item(item: NewsItem, emoji: str, headline_bn: str, sentiment: str) -> bool:
    """সবসময় সর্বোচ্চ ১টি ছবি পাঠায় (কখনো অ্যালবাম/sendMediaGroup নয়):
    সোর্সে ছবি থাকলে প্রথম ইউনিক ছবিটি -> ছবি না থাকলে Pollinations.ai দিয়ে
    ১টি AI ছবি বানিয়ে পাঠানো -> সব ব্যর্থ হলে শুধু টেক্সট।"""
    caption = build_caption(emoji, headline_bn, item.link, sentiment, item.source_type)
    raw_images = [u for u in item.images if u and u.startswith("http")]
    valid_images = dedupe_image_urls(raw_images)

    if valid_images:
        log.info("সোর্সের প্রাইমারি/প্রথম ইউনিক ছবি দিয়ে ১টি ছবি হিসেবে পোস্ট করা হচ্ছে")
        return send_single_photo(caption, image_url=valid_images[0])

    if Config.ENABLE_AI_IMAGE:
        log.info("সোর্সে কোনো ছবি নেই — Pollinations.ai দিয়ে ১টি ছবি তৈরি করা হচ্ছে")
        img_prompt = generate_image_prompt(item)
        image_bytes = generate_ai_image_bytes(img_prompt)
        if image_bytes:
            return send_single_photo(caption, image_bytes=image_bytes)

    log.info("কোনো ছবি পাওয়া যায়নি — শুধু টেক্সট আকারে পোস্ট করা হচ্ছে")
    return send_text_message(caption)


