# BTC/ETH রিয়েল-টাইম প্রাইস মাইলস্টোন অ্যালার্ট
# ---------------------------------------------------------------------------
PRICE_SYMBOLS = {
    # symbol (Binance) -> (কয়েনের নাম, symbol, milestone step, ফুটার টেক্সট, বৃত্তের রঙ)
    "BTCUSDT": ("Bitcoin", "BTC", Config.BTC_MILESTONE_STEP, "BTC PRICE", "#F7931A"),
    "ETHUSDT": ("Ethereum", "ETH", Config.ETH_MILESTONE_STEP, "ETH PRICE", "#3C3C50"),
}

COINGECKO_IDS = {"BTCUSDT": "bitcoin", "ETHUSDT": "ethereum"}


def fetch_spot_price(symbol: str) -> Optional[float]:
    """সম্পূর্ণ ফ্রি পাবলিক API দিয়ে লাইভ স্পট প্রাইস আনে — প্রথমে Binance,
    সেটা ব্যর্থ হলে (রিজিওন-ব্লক/ডাউনটাইম) স্বয়ংক্রিয়ভাবে CoinGecko তে
    ফলব্যাক করে। কোনো API key প্রয়োজন হয় না।"""
    try:
        resp = requests.get(
            Config.BINANCE_TICKER_URL, params={"symbol": symbol}, timeout=10
        )
        resp.raise_for_status()
        return float(resp.json()["price"])
    except Exception as e:
        log.warning(f"Binance থেকে {symbol} এর দাম আনতে ব্যর্থ, CoinGecko চেষ্টা করা হচ্ছে: {e}")

    try:
        coin_id = COINGECKO_IDS.get(symbol)
        if not coin_id:
            return None
        resp = requests.get(
            Config.COINGECKO_PRICE_URL,
            params={"ids": coin_id, "vs_currencies": "usd"},
            timeout=10,
        )
        resp.raise_for_status()
        return float(resp.json()[coin_id]["usd"])
    except Exception as e:
        log.error(f"CoinGecko থেকেও {symbol} এর দাম আনতে ব্যর্থ: {e}")
        return None


def fetch_recent_candles(symbol: str, limit: int = 4) -> List[Tuple[float, float]]:
    """Binance থেকে সর্বশেষ কয়েকটি ১৫-মিনিটের ক্যান্ডেল (klines) আনে এবং
    প্রতিটির (open, close) টাপল রিটার্ন করে — প্রাইস কার্ডের মিনি
    ক্যান্ডেলস্টিকগুলো এই আসল ডেটা অনুযায়ী সবুজ/লাল রঙ করা হয়। ব্যর্থ হলে
    খালি লিস্ট রিটার্ন করে (কার্ড তখন নিরপেক্ষ ধূসর ক্যান্ডেল দেখাবে)।"""
    try:
        resp = requests.get(
            Config.BINANCE_KLINES_URL,
            params={"symbol": symbol, "interval": "15m", "limit": limit},
            timeout=10,
        )
        resp.raise_for_status()
        data = resp.json()
        candles = []
        for k in data:
            open_price = float(k[1])
            close_price = float(k[4])
            candles.append((open_price, close_price))
        return candles
    except Exception as e:
        log.warning(f"{symbol} এর ক্যান্ডেল ডেটা আনতে ব্যর্থ: {e}")
        return []


